-- Catalog seed, generated by GET /api/dev/seed-sql from the app's own data. Idempotent (upserts only).

on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, period = excluded.period, color = excluded.color, image = excluded.image, position = excluded.position, active = excluded.active, metadata = excluded.metadata;

on conflict (id) do update set world_id = excluded.world_id, title = excluded.title, summary = excluded.summary, level = excluded.level, image = excluded.image, source = excluded.source, steps = excluded.steps, position = excluded.position, active = excluded.active, metadata = excluded.metadata;

on conflict (id) do update set world_id = excluded.world_id, lesson_id = excluded.lesson_id, kind = excluded.kind, title = excluded.title, summary = excluded.summary, image = excluded.image, round_size = excluded.round_size, question_count = excluded.question_count, xp_per_correct = excluded.xp_per_correct, source = excluded.source, position = excluded.position, active = excluded.active, metadata = excluded.metadata;

on conflict (id) do update set name = excluded.name, name_ta = excluded.name_ta, category = excluded.category, era = excluded.era, sort_order = excluded.sort_order, tags = excluded.tags, world_id = excluded.world_id, glyph = excluded.glyph, image = excluded.image, bio = excluded.bio, poet_names = excluded.poet_names, active = excluded.active;

on conflict (slug) do update set name = excluded.name, name_ta = excluded.name_ta, layer = excluded.layer, period = excluded.period, description = excluded.description, unit = excluded.unit, item_count = excluded.item_count, world_id = excluded.world_id, authors = excluded.authors, reference = excluded.reference, status = excluded.status, metadata = excluded.metadata;

on conflict (id) do update set title = excluded.title, description = excluded.description, goal = excluded.goal, xp = excluded.xp, diamonds = excluded.diamonds, position = excluded.position;

on conflict (id) do update set label = excluded.label, position = excluded.position;

on conflict (slug) do update set author_id = excluded.author_id, is_official = excluded.is_official, topic_id = excluded.topic_id, title = excluded.title, body = excluded.body, tags = excluded.tags, ref_label = excluded.ref_label, ref_href = excluded.ref_href, created_at = excluded.created_at;

-- Profiles for anyone who signed up before this schema existed (the trigger covers everyone after).
select u.id, u.email,
       nullif(left(coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'), 80), ''),
       coalesce(u.raw_user_meta_data ->> 'avatar_url', u.raw_user_meta_data ->> 'picture'),
       coalesce(u.raw_app_meta_data ->> 'provider', 'email')
from auth.users u
on conflict (id) do nothing;
