insert into public.worlds (id, title, subtitle, description, period, color, image, position, active, metadata) values
  ('thirukkural', 'Thirukkural World', 'Ethics for Life', 'Thiruvalluvar''s couplets on aṟam (virtue), poruḷ (wealth) and iṉpam (love), with three Tamil commentaries and an English translation.', 'c. 300–600 CE', '#3f7a45', '/worlds/thirukkural.webp', 0, true, '{"i18n_key":"thirukkural"}'::jsonb),
  ('sangam', 'Sangam World', 'People · Love · Nature', 'Classical anthologies of akam (inner life) and puṟam (public life), set in the five thiṇai landscapes.', 'c. 300 BCE–300 CE', '#0e5a6e', '/worlds/sangam.webp', 1, true, '{"i18n_key":"sangam"}'::jsonb),
  ('bhakti', 'Bhakti World', 'Devotion · Poetry · Values', 'Śaiva and Vaiṣṇava devotional hymns — Tēvāram, Nālāyira Divya Prabandham — and the Tirumantiram.', 'c. 600–900 CE', '#b07a1f', '/worlds/bhakti.webp', 2, true, '{"i18n_key":"bhakti"}'::jsonb),
  ('grammar', 'Grammar World', 'Language · Structure · Beauty', 'Tolkāppiyam: the oldest extant Tamil grammar, in three books — letters (Eḻuttu), words (Col) and subject matter (Poruḷ).', 'dating contested', '#8a4b22', '/worlds/grammar.webp', 3, true, '{"i18n_key":"grammar"}'::jsonb),
  ('history', 'History World', 'Kings · Culture · Heritage', 'The twin epics Cilappatikāram and Maṇimēkalai: courts, cities, trade and ethics in narrative verse.', 'c. 2nd–6th century CE', '#5a3f73', '/worlds/history.webp', 4, true, '{"i18n_key":"history"}'::jsonb)
insert into public.lessons (id, world_id, title, summary, level, image, source, steps, position, active, metadata) values
  ('muppal', 'thirukkural', 'The Three Books — Muppāl', 'Virtue, wealth and love: the opening couplet of each book.', 'Beginner', '/worlds/thirukkural.webp', 'Tirukkuṟaḷ · datasets/Thirukkural.pdf', '[{"ta":"குறள் 1 · கடவுள் வாழ்த்து","en":"Kural 1 — Praise of God","note":"As all letters have the letter A for their first, so the world has the eternal God for its first.","verse":{"id":"KURAL-1","text":"Tirukkural","textTa":"திருக்குறள்","number":"1","lines":["அகர முதல எழுத்தெல்லாம் ஆதி","பகவன் முதற்றே உலகு."],"english":"A, as its first of letters, every speech maintains; The \"Primal Deity\" is first through all the world''s domains.","url":"/academy/thirukkural/1"}},{"ta":"குறள் 381 · இறைமாட்சி","en":"Kural 381 — Merits of King","note":"He who possesses these six things, an army, a people, wealth, ministers, friends and a fortress, is a lion among kings.","verse":{"id":"KURAL-381","text":"Tirukkural","textTa":"திருக்குறள்","number":"381","lines":["படைகுடி கூழ்அமைச்சு நட்பரண் ஆறும்","உடையான் அரசருள் ஏறு."],"english":"An army, people, wealth, a minister, friends, fort: six things- Who owns them all, a lion lives amid the kings.","url":"/academy/thirukkural/381"}},{"ta":"குறள் 1081 · தகையணங்குறுத்தல்","en":"Kural 1081 — Fascination","note":"Is this jewelled female a celestial, a choice peahen, or a human being ? My mind is perplexed.","verse":{"id":"KURAL-1081","text":"Tirukkural","textTa":"திருக்குறள்","number":"1081","lines":["அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை","மாதர்கொல் மாலும்என் நெஞ்சு."],"english":"Goddess? or peafowl rare? She whose ears rich jewels wear, Is she a maid of human kind? All wildered is my mind!.","url":"/academy/thirukkural/1081"}}]'::jsonb, 0, true, '{"step_count":3}'::jsonb),
  ('kural-god', 'thirukkural', 'Praise of God — Chapter 1', 'The ten couplets that open the Tirukkuṟaḷ, with translation and commentary.', 'Beginner', '/lessons/temple.webp', 'Tirukkuṟaḷ, அதிகாரம் 1', '[{"ta":"குறள் 1 · கடவுள் வாழ்த்து","en":"Kural 1 — Praise of God","note":"As all letters have the letter A for their first, so the world has the eternal God for its first.","verse":{"id":"KURAL-1","text":"Tirukkural","textTa":"திருக்குறள்","number":"1","lines":["அகர முதல எழுத்தெல்லாம் ஆதி","பகவன் முதற்றே உலகு."],"english":"A, as its first of letters, every speech maintains; The \"Primal Deity\" is first through all the world''s domains.","url":"/academy/thirukkural/1"}},{"ta":"குறள் 2 · கடவுள் வாழ்த்து","en":"Kural 2 — Praise of God","note":"What Profit have those derived from learning, who worship not the good feet of Him who is possessed of pure knowledge ?.","verse":{"id":"KURAL-2","text":"Tirukkural","textTa":"திருக்குறள்","number":"2","lines":["கற்றதனால் ஆய பயனென்கொல் வாலறிவன்","நற்றாள் தொழாஅர் எனின்."],"english":"No fruit have men of all their studied lore, Save they the ''Purely Wise One''s''feet adore.","url":"/academy/thirukkural/2"}},{"ta":"குறள் 3 · கடவுள் வாழ்த்து","en":"Kural 3 — Praise of God","note":"They who are united to the glorious feet of Him who occupies swiftly the flower of the mind, shall flourish in the highest of worlds (heaven).","verse":{"id":"KURAL-3","text":"Tirukkural","textTa":"திருக்குறள்","number":"3","lines":["மலர்மிசை ஏகினான் மாணடி சேர்ந்தார்","நிலமிசை நீடுவாழ் வார்."],"english":"His feet, ''Who o''er the full-blown flower hath past,'' who gain In bliss long time shall dwell above this earthly plain.","url":"/academy/thirukkural/3"}},{"ta":"குறள் 4 · கடவுள் வாழ்த்து","en":"Kural 4 — Praise of God","note":"To those who meditate the feet of Him who is void of desire or aversion, evil shall never come.","verse":{"id":"KURAL-4","text":"Tirukkural","textTa":"திருக்குறள்","number":"4","lines":["வேண்டுதல் வேண்டாமை இலானடி சேர்ந்தார்க்கு","யாண்டும் இடும்பை இல."],"english":"His foot, ''Whom want affects not, irks not grief,'' who gain Shall not, through every time, of any woes complain.","url":"/academy/thirukkural/4"}},{"ta":"குறள் 5 · கடவுள் வாழ்த்து","en":"Kural 5 — Praise of God","note":"The two-fold deeds that spring from darkness shall not adhere to those who delight in the true praise of God.","verse":{"id":"KURAL-5","text":"Tirukkural","textTa":"திருக்குறள்","number":"5","lines":["இருள்சேர் இருவினையும் சேரா இறைவன்","பொருள்சேர் புகழ்புரிந்தார் மாட்டு."],"english":"The men, who on the ''King''s'' true praised delight to dwell, Affects not them the fruit of deeds done ill or well.","url":"/academy/thirukkural/5"}},{"ta":"குறள் 6 · கடவுள் வாழ்த்து","en":"Kural 6 — Praise of God","note":"Those shall long proposer who abide in the faultless way of Him who has destroyed the five desires of the senses.","verse":{"id":"KURAL-6","text":"Tirukkural","textTa":"திருக்குறள்","number":"6","lines":["பொறிவாயில் ஐந்தவித்தான் பொய்தீர் ஒழுக்க","நெறிநின்றார் நீடுவாழ் வார்."],"english":"Long live they blest, who ''ve stood in path from falsehood freed; His, ''Who quenched lusts that from the sense-gates five proceed''.","url":"/academy/thirukkural/6"}},{"ta":"குறள் 7 · கடவுள் வாழ்த்து","en":"Kural 7 — Praise of God","note":"Anxiety of mind cannot be removed, except from those who are united to the feet of Him who is incomparable.","verse":{"id":"KURAL-7","text":"Tirukkural","textTa":"திருக்குறள்","number":"7","lines":["தனக்குவமை இல்லாதான் தாள்சேர்ந்தார்க் கல்லால்","மனக்கவலை மாற்றல் அரிது."],"english":"Unless His foot, ''to Whom none can compare,gain, ''This hard for mind to find relief from anxious pain.","url":"/academy/thirukkural/7"}},{"ta":"குறள் 8 · கடவுள் வாழ்த்து","en":"Kural 8 — Praise of God","note":"None can swim the sea of vice, but those who are united to the feet of that gracious Being who is a sea of virtue.","verse":{"id":"KURAL-8","text":"Tirukkural","textTa":"திருக்குறள்","number":"8","lines":["அறவாழி அந்தணன் தாள்சேர்ந்தார்க் கல்லால்","பிறவாழி நீந்தல் அரிது."],"english":"Unless His feet ''the Sea of Good, the Fair and Bountiful,'' men gain, ''Tis hard the further bank of being''s changeful sea to attain.","url":"/academy/thirukkural/8"}},{"ta":"குறள் 9 · கடவுள் வாழ்த்து","en":"Kural 9 — Praise of God","note":"The head that worships not the feet of Him who is possessed of eight attributes, is as useless as a sense without the power of sensation.","verse":{"id":"KURAL-9","text":"Tirukkural","textTa":"திருக்குறள்","number":"9","lines":["கோளில் பொறியின் குணமிலவே எண்குணத்தான்","தாளை வணங்காத் தலை."],"english":"Before His foot, ''the Eight-fold Excellence,'' with unbent head, Who stands, like palsied sense, is to all living functions dead.","url":"/academy/thirukkural/9"}},{"ta":"குறள் 10 · கடவுள் வாழ்த்து","en":"Kural 10 — Praise of God","note":"None can swim the great sea of births but those who are united to the feet of God.","verse":{"id":"KURAL-10","text":"Tirukkural","textTa":"திருக்குறள்","number":"10","lines":["பிறவிப் பெருங்கடல் நீந்துவர் நீந்தார்","இறைவன் அடிசேரா தார்."],"english":"They swim the sea of births, the ''Monarch''s'' foot who gain; None others reach the shore of being''s mighty main.","url":"/academy/thirukkural/10"}}]'::jsonb, 1, true, '{"step_count":10}'::jsonb),
  ('kural-learning', 'thirukkural', 'Learning — Chapter 40', 'கல்வி: why learning is the wealth that never perishes.', 'Intermediate', '/lessons/books.webp', 'Tirukkuṟaḷ, அதிகாரம் 40', '[{"ta":"குறள் 391 · கல்வி","en":"Kural 391 — Learning","note":"Let a man learn thoroughly whatever he may learn, and let his conduct be worthy of his learning.","verse":{"id":"KURAL-391","text":"Tirukkural","textTa":"திருக்குறள்","number":"391","lines":["கற்க கசடறக் கற்பவை கற்றபின்","நிற்க அதற்குத் தக."],"english":"So learn that you may full and faultless learning gain, Then in obedience meet to lessons learnt remain.","url":"/academy/thirukkural/391"}},{"ta":"குறள் 392 · கல்வி","en":"Kural 392 — Learning","note":"Letters and numbers are the two eyes of man.","verse":{"id":"KURAL-392","text":"Tirukkural","textTa":"திருக்குறள்","number":"392","lines":["எண்ணென்ப ஏனை எழுத்தென்ப இவ்விரண்டும்","கண்ணென்ப வாழும் உயிர்க்கு.."],"english":"The twain that lore of numbers and of letters give Are eyes, the wise declare, to all on earth that live.","url":"/academy/thirukkural/392"}},{"ta":"குறள் 393 · கல்வி","en":"Kural 393 — Learning","note":"The learned are said to have eyes, but the unlearned have (merely) two sores in their face.","verse":{"id":"KURAL-393","text":"Tirukkural","textTa":"திருக்குறள்","number":"393","lines":["கண்ணுடையர் என்பவர் கற்றோர் முகத்திரண்டு","புண்ணுடையர் கல்லா தவர்."],"english":"Men who learning gain have eyes, men say; Blockheads'' faces pairs of sores display.","url":"/academy/thirukkural/393"}},{"ta":"குறள் 394 · கல்வி","en":"Kural 394 — Learning","note":"It is the part of the learned to give joy to those whom they meet, and on leaving, to make them think (Oh! when shall we meet them again).","verse":{"id":"KURAL-394","text":"Tirukkural","textTa":"திருக்குறள்","number":"394","lines":["உவப்பத் தலைக்கூடி உள்ளப் பிரிதல்","அனைத்தே புலவர் தொழில்."],"english":"You meet with joy, with pleasant thought you part; Such is the learned scholar''s wonderous art!.","url":"/academy/thirukkural/394"}},{"ta":"குறள் 395 · கல்வி","en":"Kural 395 — Learning","note":"The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy.","verse":{"id":"KURAL-395","text":"Tirukkural","textTa":"திருக்குறள்","number":"395","lines":["உடையார்முன் இல்லார்போல் ஏக்கற்றுங் கற்றார்","கடையரே கல்லா தவர்."],"english":"With soul submiss they stand, as paupers front a rich man''s face; Yet learned men are first; th''unlearned stand in lowest place.","url":"/academy/thirukkural/395"}},{"ta":"குறள் 396 · கல்வி","en":"Kural 396 — Learning","note":"Water will flow from a well in the sand in proportion to the depth to which it is dug, and knowledge will flow from a man in proportion to his learning.","verse":{"id":"KURAL-396","text":"Tirukkural","textTa":"திருக்குறள்","number":"396","lines":["தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக்","கற்றனைத் தூறும் அறிவு."],"english":"In sandy soil, when deep you delve, you reach the springs below; The more you learn, the freer streams of wisdom flow.","url":"/academy/thirukkural/396"}},{"ta":"குறள் 397 · கல்வி","en":"Kural 397 — Learning","note":"How is it that any one can remain without learning, even to his death, when (to the learned man) every country is his own (country), and every town his own (town) ?.","verse":{"id":"KURAL-397","text":"Tirukkural","textTa":"திருக்குறள்","number":"397","lines":["யாதானும் நாடாமால் ஊராமால் என்னொருவன்","சாந்துணையுங் கல்லாத வாறு."],"english":"The learned make each land their own, in every city find a home; Who, till they die; learn nought, along what weary ways they roam!.","url":"/academy/thirukkural/397"}},{"ta":"குறள் 398 · கல்வி","en":"Kural 398 — Learning","note":"The learning, which a man has acquired in one birth, will yield him pleasure during seven births.","verse":{"id":"KURAL-398","text":"Tirukkural","textTa":"திருக்குறள்","number":"398","lines":["ஒருமைக்கண் தான்கற்ற கல்வி ஒருவற்கு","எழுமையும் ஏமாப் புடைத்து."],"english":"The man who store of learning gains, In one, through seven worlds, bliss attains.","url":"/academy/thirukkural/398"}},{"ta":"குறள் 399 · கல்வி","en":"Kural 399 — Learning","note":"The learned will long (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it.","verse":{"id":"KURAL-399","text":"Tirukkural","textTa":"திருக்குறள்","number":"399","lines":["தாமின் புறுவது உலகின் புறக்கண்டு","காமுறுவர் கற்றறிந் தார்."],"english":"Their joy is joy of all the world, they see; thus more The learners learn to love their cherished lore.","url":"/academy/thirukkural/399"}},{"ta":"குறள் 400 · கல்வி","en":"Kural 400 — Learning","note":"Learning is the true imperishable riches; all other things are not riches.","verse":{"id":"KURAL-400","text":"Tirukkural","textTa":"திருக்குறள்","number":"400","lines":["கேடில் விழுச்செல்வம் கல்வி யொருவற்கு","மாடல்ல மற்றை யவை."],"english":"Learning is excellence of wealth that none destroy; To man nought else affords reality of joy.","url":"/academy/thirukkural/400"}}]'::jsonb, 2, true, '{"step_count":10}'::jsonb),
  ('five-thinai', 'sangam', 'The Five Thiṇai', 'Every feeling has a landscape: mountain, forest, farmland, seashore, desert.', 'Beginner', '/lessons/kurinji.webp', 'Tolkāppiyam, Poruḷatikāram · Sentamizh corpus', '[{"ta":"குறிஞ்சி","en":"Kuṟiñci — Mountain","note":"Union, joy, secret love","verse":{"id":"KURU-001","text":"Kuruntokai","textTa":"குறுந்தொகை","number":"1","lines":[", அவனுடைய கையுறையை மறுத்து","செங்களம்படக் கொன்று அவுணர்த் தேய்த்த","செங்கோல் அம்பின் செங்கோட்டி யானைக்","கழல் தொடிச் சேஎய் குன்றம்,","குருதிப் பூவின் குலைக் காந்தட்டே."],"english":"The mountain of Murukan,\nthe red god wearing whirling\nbracelets,\nwho vanquished demons in the\nred battlefield, his thick arrows\nand elephant’s tusks turning red,\nhas clusters of blood-red glory\nlily blossoms.","url":"https://sangamtranslationsbyvaidehi.com/ettuthokai-kurunthokai-1-200/"}},{"ta":"முல்லை","en":"Mullai — Forest","note":"Waiting, patience, hope","verse":{"id":"KURU-021","text":"Kuruntokai","textTa":"குறுந்தொகை","number":"21","lines":["வண்டுபடத் ததைந்த கொடி இணர் இடையிடுபு","பொன் செய் புனை இழை கட்டிய மகளிர்","கதுப்பின் தோன்றும் புதுப் பூங்கொன்றைக்","கானம் கார் எனக் கூறினும்,","யானோ தேறேன், அவர் பொய் வழங்கலரே."],"english":"In the forest, the kondrai trees\n……….with their dense, trailing\n……….flower clusters that have\n……….bloomed for bees to swarm,\n……….looking like the tresses of\n……….young woman decorated with\n……….beautiful golden ornaments,\nare trying to tell me that the rainy\nseason is here.\nI do not believe it.  My lover does\nnot lie to me.","url":"https://sangamtranslationsbyvaidehi.com/ettuthokai-kurunthokai-1-200/"}},{"ta":"மருதம்","en":"Marutam — Farmland","note":"Conflict, infidelity","verse":{"id":"KURU-008","text":"Kuruntokai","textTa":"குறுந்தொகை","number":"8","lines":[", தலைவியின் தோழியர் கேட்கும்படி","கழனி மாஅத்து விளைந்து உகு தீம் பழம்","பழன வாளை கதூஉம் ஊரன்,","எம் இல் பெருமொழி கூறித், தம் இல்","கையும் காலும் தூக்கத் தூக்கும்","ஆடிப் பாவை போல,","மேவன செய்யும் தன் புதல்வன் தாய்க்கே."],"english":"The man from the town,\nwhere pond vālai fish seize\nsweet fruits that ripen and\ndrop from a mango tree\nfrom the nearby field, talks big\nat my place.\nBut when he’s at his home, he’s\nlike the mirror image of a puppet\nthat lifts its hands and legs when\na puppeteer lifts them, reflecting\nthe wishes of his son’s mother.","url":"https://sangamtranslationsbyvaidehi.com/ettuthokai-kurunthokai-1-200/"}},{"ta":"நெய்தல்","en":"Neytal — Seashore","note":"Longing, sorrow","verse":{"id":"KURU-004","text":"Kuruntokai","textTa":"குறுந்தொகை","number":"4","lines":["நோம் என் நெஞ்சே! நோம் என் நெஞ்சே!","இமை தீய்ப்பன்ன கண்ணீர் தாங்கி,","அமைதற்கு அமைந்த நம் காதலர்,","அமைவு இலர் ஆகுதல், நோம் என் நெஞ்சே."],"english":"My heart aches!  My heart aches!\nMy perfect lover who consoled me,\nwhen I cried hot tears that almost\nscalded my eye lids, has changed.\nMy heart aches!","url":"https://sangamtranslationsbyvaidehi.com/ettuthokai-kurunthokai-1-200/"}},{"ta":"பாலை","en":"Pālai — Desert","note":"Separation, hardship","verse":{"id":"KURU-007","text":"Kuruntokai","textTa":"குறுந்தொகை","number":"7","lines":["வில்லோன் காலன கழலே, தொடியோள்","மெல்லடி மேலவும் சிலம்பே, நல்லோர்","யார் கொல் அளியர் தாமே, ஆரியர்","கயிறாடு பறையின் கால் பொரக் கலங்கி","வாகை வெண் நெற்று ஒலிக்கும்","வேய் பயில் அழுவம் முன்னியோரே?"],"english":"The man bearing a bow has war\nanklets on his feet; the young woman\nwearing bangles has anklets on her\ndelicate feet.\nWho are these pitiful, nice people going\non this desert path filled with bamboo,\nwhere the wind whips and the light colored\nvākai seedpods rattle like the drums of\nAryan acrobats dancing on tightropes?","url":"https://sangamtranslationsbyvaidehi.com/ettuthokai-kurunthokai-1-200/"}}]'::jsonb, 3, true, '{"step_count":5}'::jsonb),
  ('akam-puram', 'sangam', 'Akam and Puram', 'Inner life and public life: the two halves of Sangam poetry.', 'Beginner', '/worlds/sangam.webp', 'Solveli ontology (Poruḷ)', '[{"ta":"அகம்","en":"Inner life","note":"Inner life (love, emotions)"},{"ta":"புறம்","en":"Outer life","note":"Outer life (war, charity, heroism)"},{"ta":"பண்பாடு","en":"Culture","note":"Tamil cultural practices and values."},{"ta":"வீரம்","en":"Heroism","note":"Heroism"},{"ta":"கொடை","en":"Charity","note":"Charity"},{"ta":"புகழ்","en":"Fame","note":"Fame"}]'::jsonb, 4, true, '{"step_count":6}'::jsonb),
  ('akam-voices', 'sangam', 'Voices of Akam', 'Who speaks in a love poem? Meet the heroine, the hero and the confidante.', 'Intermediate', '/lessons/coast.webp', 'Solveli ontology (Akam)', '[{"ta":"களவு","en":"Premarital love","note":"Kalavu (premarital love) theme in Akam poetics."},{"ta":"கற்பு","en":"Marital love","note":"Karpu (marital love) theme in Akam poetics."},{"ta":"தலைவன்","en":"Hero","note":"The male protagonist in Akam poetry."},{"ta":"தலைவி","en":"Heroine","note":"The female protagonist in Akam poetry."},{"ta":"தோழி","en":"Companion","note":"The confidante/friend character in Akam poetry."},{"ta":"செவிலி","en":"Nurse","note":"The caretaker/mother-figure character in Akam poetry."}]'::jsonb, 5, true, '{"step_count":6}'::jsonb),
