  ('ezhuthu', 'grammar', 'Letters — Eḻuttu', 'Vowels, consonants and their combinations, as Tolkāppiyam begins.', 'Beginner', '/lessons/books.webp', 'Tolkāppiyam, Eḻuttatikāram · Solveli ontology', '[{"ta":"உயிர் எழுத்து","en":"Vowels","note":"Tamil vowels"},{"ta":"மெய் எழுத்து","en":"Consonants","note":"Tamil consonants"},{"ta":"உயிர்மெய் எழுத்து","en":"Vowel-Consonant","note":"Vowel–consonant combinations"},{"ta":"சொல்","en":"Word","note":"Word formation rules"},{"ta":"ஃ","en":"Aytham","note":"Special Tamil character used in classical grammar."},{"ta":"குறில்","en":"Short vowels","note":"Short vowels"},{"ta":"நெடில்","en":"Long vowels","note":"Long vowels"},{"ta":"ஒற்று","en":"Dependent consonants","note":"Dependent consonants"}]'::jsonb, 7, true, '{"step_count":8}'::jsonb),
  ('sol', 'grammar', 'Words — Col', 'Nouns, verbs, particles: how Tamil sorts its words.', 'Beginner', '/worlds/grammar.webp', 'Tolkāppiyam, Collatikāram · Solveli ontology', '[{"ta":"பெயர்","en":"Noun","note":"Nouns"},{"ta":"வினை","en":"Verb","note":"Verbs"},{"ta":"இடை","en":"Particle","note":"Particles / connectors"},{"ta":"உரி","en":"Qualifier","note":"Qualitative / descriptive words"},{"ta":"புணர்ச்சி","en":"Combination","note":"Word combination rules"},{"ta":"தொகை","en":"Compound","note":"Compound formations"},{"ta":"திரிபு","en":"Transformation","note":"Word transformation"},{"ta":"வேற்றுமை","en":"Case markers","note":"Noun case system (vetrumai) in Tamil grammar."},{"ta":"விகுதி","en":"Suffix","note":"Inflectional suffixes used in word formation."}]'::jsonb, 8, true, '{"step_count":9}'::jsonb),
  ('three-books', 'grammar', 'The Three Books', 'Tolkāppiyam''s structure — and the first sūtra of each book.', 'Intermediate', '/lessons/desk.webp', 'Tolkāppiyam · Project Madurai', '[{"ta":"எழுத்ததிகாரம்","en":"Eḻuttatikāram — the book of letters","note":"நூல் மரபு · sūtra 1: எழுத்து எனப்படுப அகரம் முதல் னகர இறுவாய் முப்பஃது என்ப சார்ந்து வரல் மரபின் மூன்று அலங்கடையே."},{"ta":"சொல்லதிகாரம்","en":"Collatikāram — the book of words","note":"கிளவியாக்கம் · sūtra 1: உயர்திணை என்மனார் மக்கட் சுட்டே அஃறிணை என்மனார் அவர் அல பிறவே ஆயிரு திணையின் இசைக்குமன சொல்லே."},{"ta":"பொருளதிகாரம்","en":"Poruḷatikāram — the book of subject matter","note":"அகத்திணையியல் · sūtra 1: கைக்கிளை முதலாப் பெருந்திணை இறுவாய் முற்படக் கிளந்த எழு திணை என்ப."}]'::jsonb, 9, true, '{"step_count":3}'::jsonb),
  ('bhakti-hymns', 'bhakti', 'Hymns of Devotion', 'Tēvāram, Divya Prabandham and Tirumantiram in their own words.', 'Intermediate', '/lessons/deity.webp', 'Sentamizh corpus · Project Madurai', '[{"ta":"தேவாரம்","en":"Thevaram 1","note":"6th–10th century CE","verse":{"id":"THEV-0001","text":"Thevaram","textTa":"தேவாரம்","number":"1","lines":["தோடுடைய செவியன் விடையேறியோர் தூவெண்மதிசூடிக்","காடுடையசுட லைப்பொடிபூசியென் னுள்ளங்கவர் கள்வன்","ஏடுடையமல ரான்முனைநாட்பணிந் தேத்த அருள்செய்த","பீடுடையபிர மாபுரமேவிய பெம்மா னிவனன்றே."],"english":null,"url":""}},{"ta":"தேவாரம்","en":"Thevaram 574","note":"6th–10th century CE","verse":{"id":"THEV-2043","text":"Thevaram","textTa":"தேவாரம்","number":"574","lines":["கைய ரிவையர் மெல்வி ரல்லவை","காட்டி யம்மலர்க் காந்த ளங்குறி","பையரா விரியும் புறவார் பனங்காட்டூர்","மெய்ய ரிவையோர் பாக மாகவும்","மேவி னாய்கழ லேத்தி நாடொறும்","பொய்யிலா அடிமை புரிந்தார்க் கருளாயே."],"english":null,"url":""}},{"ta":"திவ்ய பிரபந்தம்","en":"Divya Prabandham 1","note":"6th–10th century CE","verse":{"id":"DIVA-0001","text":"Divya Prabandham","textTa":"திவ்ய பிரபந்தம்","number":"1","lines":["பல்லாண்டு பல்லாண்டு பல்லாயிரத்தாண்டு","பலகோடிநூறாயிரம்","மல்லாண்டதிண்தோள்மணிவண்ணா. உன்","செவ்வடிசெவ்விதிருக்காப்பு. (2)","அறுசீர்க்கழிநெடிலடியாசிரியவிருத்தம்"],"english":null,"url":""}},{"ta":"திவ்ய பிரபந்தம்","en":"Divya Prabandham 1972","note":"6th–10th century CE","verse":{"id":"DIVA-1972","text":"Divya Prabandham","textTa":"திவ்ய பிரபந்தம்","number":"1972","lines":["மன்னிலங்கு பாரதத்துத் தேரூர்ந்து, மாவலியைப்","பொன்னிலங்கு திண்விலங்கில் வைத்துப் பொருகடல்சூழ்","தென்னிலங்கை யீடழித்த தேவர்க் கிதுகாணீர்","என்னிலங்கு சங்கோ டெழில்தோற் றிருந்தேனே. (2)"],"english":null,"url":""}},{"ta":"திருமந்திரம்","en":"Thirumanthiram 1","note":"6th–10th century CE","verse":{"id":"THIR-0001","text":"Thirumanthiram","textTa":"திருமந்திரம்","number":"1","lines":["ஒன்றவன் தானே இரண்டவன் இன்னருள்","நின்றனன் மூன்றினுள் நான்குணர்ந் தான்ஐந்து","வென்றனன் ஆறு விரிந்தனன் ஏழும்பர்ச்","சென்றனன் தானிருந் தான்உணர்ந் தெட்டே."],"english":null,"url":""}},{"ta":"திருமந்திரம்","en":"Thirumanthiram 171","note":"6th–10th century CE","verse":{"id":"THIR-0171","text":"Thirumanthiram","textTa":"திருமந்திரம்","number":"171","lines":["ஈட்டிய தேன்பூ மணங்கண் டிரதமும்","கூட்டிக் கொணர்ந்தொரு கொம்பிடை வைத்திடும்","ஓட்டித் துரந்திட்டு அதுவலி யார்கொளக்","காட்டிக் கொடுத்தது கைவிட்ட வாறே."],"english":null,"url":""}}]'::jsonb, 10, true, '{"step_count":6}'::jsonb),
  ('twin-epics', 'history', 'The Twin Epics', 'Cities, courts and trade in Cilappatikāram and Maṇimēkalai.', 'Intermediate', '/lessons/harbor.webp', 'Sentamizh corpus · Project Madurai', '[{"ta":"சிலப்பதிகாரம்","en":"Silappatikaram 1","note":"2nd–6th century CE","verse":{"id":"SILA-001","text":"Silappatikaram","textTa":"சிலப்பதிகாரம்","number":"1","lines":["(சிந்தியல் வெண்பாக்கள்)","திங்களைப் போற்றுதும் திங்களைப் போற்றுதும்","கொங்கலர்த்தார்ச் சென்னி குளிர்வெண் குடைபோன்றிவ்","வங்கண் உலகுஅளித்த லான்.","ஞாயிறு போற்றுதும் ஞாயிறு போற்றுதும்","காவிரி நாடன் திகிரிபோல் பொற்கோட்டு","மேரு வலம்திரி தலான்.","மாமழை போற்றுதும் மாமழை போற்றுதும்","நாமநீர் வேலி உலகிற்கு அவனளிபோல்","மேநின்று தாஞ்சுரத்த லான்.","பூம்புகார் போற்றுதும் பூம்புகார் போற்றுதும்","வீங்குநீர் வேலி உலகிற்கு அவன்குலத்தொடு","ஓங்கிப் பரந்துஒழுக லான். ஆங்கு,","பொதியில் ஆயினும் இமயம் ஆயினும்","பதிஎழு அறியாப் பழங்குடி கெழீஇய","பொதுஅறு சிறப்பின் புகாரே ஆயினும்","நடுக்கின்றி நிலைஇய என்பது அல்லதை","ஒடுக்கம் கூறார் உயர்ந்தோர் உண்மையின்","முடித்த கேள்வி முழுதுணர்ந் தோரே.","அதனால்,","நாகநீள் நகரொடு நாகநாடு அதனொடு","போகம்நீள் புகழ்மன்னும் புகார்நகர் அதுதன்னில்","மாகவான் நிகர்வண்கை மாநாய்கன் குலக்கொம்பர்","ஈகைவான் கொடியன்னாள் ஈராறுஆண்டு அகவையாள்,","அவளுந்தான்,","போதில்ஆர் திருவினாள் புகழுடை வடிவென்றும்","தீதிலா வடமீனின் திறம்இவள் திறம்என்றும்","மாதரார் தொழுதுஏத்த வயங்கிய பெருங்குணத்துக்","காதலாள் பெயர்மன்னும் கண்ணகிஎன் பாள்மன்னோ,","ஆங்கு,","பெருநிலம் முழுதாளும் பெருமகன் தலைவைத்த","ஒருதனிக் குடிகளொடு உயர்ந்தோங்கு செல்வத்தான்","வருநிதி பிறர்க்குஆர்த்தும் மாசாத்து வான்என்பான்","இருநிதிக் கிழவன்மகன் ஈரெட்டுஆண்டு அகவையான்,","அவனுந்தான்,","மண்தேய்த்த புகழினான் மதிமுக மடவார்தம்","பண்தேய்த்த மொழியினார் ஆயத்துப் பாராட்டிக்","கண்டுஏத்தும் செவ்வேள்என்று இசைபோக்கிக் காதலால்","கொண்டுஏத்தும் கிழமையான் கோவலன்என் பான்மன்னோ.","அவரை,","இருபெருங் குரவரும் ஒருபெரு நாளால்","மணஅணி காண மகிழ்ந்தனர், மகிழ்ந்துழி","யானை எருத்தத்து அணிஇழையார் மேல்இரீஇ","மாநகர்க்கு ஈந்தார் மணம்.","அவ்வழி,","முரசுஇயம்பின, முருகுஅதிர்ந்தன, முறைஎழுந்தன","பணிலம்,வெண்குடை","அரசுஎழுந்ததொர் படிஎழுந்தன, அகலுள்மங்கல அணிஎழுந்தது.","மாலைதாழ் சென்னி வயிரமணித்  àணகத்து","நீல விதானத்து நித்திலப்பூம் பந்தர்க்கீழ்","வான்ஊர் மதியம் சகடுஅணைய வானத்துச்","சாலி ஒருமீன் தகையாளைக் கோவலன்","மாமுது பார்ப்பான் மறைவழி காட்டிடத்","தீவலம் செய்வது காண்பார்க்கண் நோன்புஎன்னை.","விரையினர் மலரினர் விளங்கு மேனியர்","உரையினர் பாட்டினர் ஒசிந்த நோக்கினர்","சாந்தினர் புகையினர் தயங்கு கோதையர்","ஏந்துஇள முலையினர் இடித்த சுண்ணத்தர்","விளக்கினர் கலத்தினர் விரித்த பாலிகை","முளைக்குட நிரையினர் முகிழ்த்த மூரலர்","போதொடு விரிகூந்தல் பொலன்நறுங் கொடிஅன்னார்","காதலற் பிரியாமல் கவவுக்கை ஞெகிழாமல்","தீதுஅறுக எனஏத்திச் சின்மலர் கொடு தூவி","அங்கண் உலகின் அருந்ததி அன்னாளை","மங்கல நல்அமளி ஏற்றினார், தங்கிய","இப்பால் இமயத்து இருத்திய வாள்வேங்கை","உப்பாலைப் பொன்கோட்டு உழையதா எப்பாலும்","செருமிகு சினவேல் செம்பியன்","ஒருதனி ஆழி உருட்டுவோன் எனவே."],"english":null,"url":""}},{"ta":"சிலப்பதிகாரம்","en":"Silappatikaram 4","note":"2nd–6th century CE","verse":{"id":"SILA-004","text":"Silappatikaram","textTa":"சிலப்பதிகாரம்","number":"4","lines":["(நிலைமண்டில ஆசிரியப்பா)","விரிகதிர் பரப்பி உலகம்முழுது ஆண்ட","ஒருதனித் திகிரி உரவோன் காணேன்","அங்கண் வானத்து அணிநிலா விரிக்கும்","திங்கள்அம் செல்வன் யாண்டுஉளன் கொல்எனத்","திசைமுகம் பசந்து செம்மலர்க் கண்கள்","முழுநீர் வார முழுமெயும் பனித்துத்","திரைநீர் ஆடை இருநில மடந்தை","அரைசுகெடுத்து அலம்வரும் அல்லற் காலை,","கறைகெழு குடிகள் கைதலை வைப்ப","அறைபோகு குடிகளொடு ஒருதிறம் பற்றி","வலம்படு தானை மன்னர் இல்வழிப்","புலம்பட இறுத்த விருந்தின் மன்னரின்","தாழ்துணை துறந்தோர் தனித்துயர் எய்தக்","காதலர்ப் புணர்ந்தோர் களிமகிழ்வு எய்தக்","குழல்வளர் முல்லையில் கோவலர் தம்மொடு","மழலைத் தும்பி வாய்வைத்து ஊத","அறுகால் குறும்புஎறிந்து அரும்புபொதி வாசம்","சிறுகால் செல்வன் மறுகில் தூற்ற","எல்வளை மகளிர் மணிவிளக்கு எடுப்ப","மல்லல் மூதூர் மாலைவந்து இருத்தென","இளையர் ஆயினும் பகைஅரசு கடியும்","செருமாண் தென்னர் குலமுதல் ஆகலின்","அந்திவா னத்து வெண்பிறை தோன்றிப்","புன்கண் மாலைக் குறும்புஎறிந்து ஓட்டிப்","பான்மையில் திரியாது பால்கதிர் பரப்பி","மீன்அரசு ஆண்ட வெள்ளி விளக்கத்து,","இல்வளர் முல்லையொடு மல்லிகை அவிழ்ந்த","பல்பூஞ் சேக்கைப் பள்ளியுள் பொலிந்து","செந்துகிர்க் கோவை சென்றுஏந்து அல்குல்","அம்துகில் மேகலை அசைந்தன வருந்த","நிலவுப்பயன் கொள்ளும் நெடுநிலா முற்றத்துக்","கலவியும் புலவியும் காதலற்கு அளித்துஆங்கு","ஆர்வ நெஞ்சமொடு கோவலற்கு எதிரிக்","கோலம் கொண்ட மாதவி அன்றியும்,","குடதிசை மருங்கின் வெள்அயிர் தன்னொடு","குணதிசை மருங்கின் கார்அகில் துறந்து","வடமலைப் பிறந்த வான்கேழ் வட்டத்துத்","தென்மலைப் பிறந்த சந்தனம் மறுகத்","தாமரைக் கொழுமுறித் தாதுபடு செழுமலர்க்","காமரு குவளைக் கழுநீர் மாமலர்ப்","பைந்தளிர்ப் படலை பருஉக்காழ் ஆரம்","சுந்தரச் சுண்ணத் துகளொடு அளைஇச்","சிந்துபு பரிந்த செழும்பூஞ் சேக்கை","மந்தமா ருதத்து மயங்கினர் மலிந்துஆங்கு","ஆவியங் கொழுநர் அகலத்து ஒடுங்கிக்","காவியங் கண்ணார் களிதுயி லெய்த","அம்செஞ் சீறடி அணிசிலம்பு ஒழிய","மென்துகில் அல்குல் மேகலை நீங்கக்","கொங்கை முன்றில் குங்குமம் எழுதாள்","மங்கல அணியின் பிறிதுஅணி மகிழாள்","கொடுங்குழை துறந்து வடிந்துவீழ் காதினள்","திங்கள் வாள்முகம் சிறுவியர்ப்பு இரியச்","செங்கயல் நெடுங்கண் அஞ்சனம் மறப்பப்","பவள வாள்நுதல் திலகம் இழப்பத்","தவள வாள்நகை கோவலன் இழப்ப","மைஇருங் கூந்தல் நெய்அணி மறப்பக்","கையறு நெஞ்சத்துக் கண்ணகி அன்றியும்","காதலர்ப் பிரிந்த மாதர் நோதக","ஊதுஉலைக் குருகின் உயிர்த்தனர் ஒடுங்கி","வேனில் பள்ளி மேவாது கழிந்து","கூதிர்ப் பள்ளிக் குறுங்கண் அடைத்து","மலயத்து ஆரமும் மணிமுத்து ஆரமும்","அலர்முலை ஆகத்து அடையாது வருந்தத்","தாழிக் குவளையொடு தண்செங் கழுநீர்","வீழ்பூஞ் சேக்கை மேவாது கழியத்","துணைபுணர் அன்னத் து஡வியிற் செறித்த","இணைஅணை மேம்படத் திருந்துதுயில் பெறாஅது","உடைப்பெருங் கொழுநரோடு ஊடல் காலத்து","இடைக்குமிழ் எறிந்து கடைக்குழை ஓட்டிக்","கலங்கா உள்ளம் கலங்கக் கடைசிவந்து","விலங்கிநிமிர் நெடுங்கண் புலம்புமுத்து உறைப்ப","அன்னம் மெல்நடை நன்னீர்ப் பொய்கை","ஆம்பல் நாறும் தேம்பொதி நறுவிரைத்","தாமரைச் செவ்வாய்த் தண்அறல் கூந்தல்","பாண்வாய் வண்டு நோதிறம் பாடக்","காண்வரு குவளைக் கண்மலர் விழிப்பப்","புள்வாய் முரசமொடு பொறிமயிர் வாரணத்து","முள்வாய்ச் சங்கம் முறைமுறை ஆர்ப்ப","உரவுநீர்ப் பரப்பின் ஊர்த்துயில் எடுப்பி","இரவுத் தலைப்பெயரும் வைகறை காறும்","அரைஇருள் யாமத்தும் பகலும் துஞ்சான்","விரைமலர் வாளியொடு கருப்புவில் ஏந்தி","மகர வெல்கொடி மைந்தன் திரிதர","நகரம் காவல் நனிசிறந் ததுஎன்."],"english":null,"url":""}},{"ta":"சிலப்பதிகாரம்","en":"Silappatikaram 7","note":"2nd–6th century CE","verse":{"id":"SILA-007","text":"Silappatikaram","textTa":"சிலப்பதிகாரம்","number":"7","lines":["சித்திரப் படத்துள்புக்குச் செழுங்கோட்டின் மலர்புனைந்து          க","மைத்தடங்கண் மணமகளிர் கோலம்போல் வனப்புஎய்திப்","பத்தரும் கோடும் ஆணியும் நரம்பும்என்று","இத்திறத்துக் குற்றம்நீங்கிய யாழ்கையில் தொழுதுவாங்கி","பண்ணல் பரிவட்டணை ஆராய்தல் தைவரல்","கண்ணிய செலவு விளையாட்டுக் கையூழ்","நண்ணிய குறும்போக்கு என்று நாட்டிய","எண்வகையால் இசைஎழீஇப்","பண்வகையால் பரிவுதீர்ந்து","மரகதமணித் தாள்செறிந்த மணிக்காந்தள் மெல்விரல்கள்","பயிர்வண்டின் கிளைபோலப் பல்நரம்பின் மிசைப்படர","வார்தல் வடித்தல் உந்தல் உறழ்தல்","சீருடன் உருட்டல் தெருட்டல் அள்ளல்","ஏர்உடைப் பட்டடைஎன இசையோர் வகுத்த","எட்டு வகையின் இசைக்கர ணத்துப்","பட்டவகைதன் செவியின்ஓர்த்(து)","ஏவலன், பின் பாணி யாதுஎனக்","கோவலன் கையாழ் நீட்ட, அவனும்","காவிரியை நோக்கினவும் கடல்கானல் வரிப்பாணியும்","மாதவிதன் மனம்மகிழ வாசித்தல் தொடங்குமன்.","வேறு (ஆற்று வரி)","திங்கள் மாலை வெண்குடையான்                           உ.","சென்னி செங்கோல் அதுஒச்சிக்","கங்கை தன்னைப் புணர்ந்தாலும்","புலவாய் வாழி காவேரி.","கங்கை தன்னைப் புணர்ந்தாலும்","புலவாது ஒழிதல் கயல்கண்ணாய்.","மங்கை மாதர் பெருங்கற்புஎன்று","அறிந்தேன் வாழி காவேரி.","மன்னும் மாலை வெண்குடையான்                                                           ௩.","வளையாச் செங்கோல் அதுஓச்சிக்","கன்னி தன்னைப் புணர்ந்தாலும்","புலவாய் வாழி காவேரி.","கன்னி தன்னைப் புணர்ந்தாலும்","புலவாது ஒழிதல் கயல்கண்ணாய்.","மன்னும் மாதர் பெருங்கற்புஎன்று","அறிந்தேன் வாழி காவேரி.","உழவர் ஓதை மதகுஓதை","உடைநீர் ஓதை தண்பதங்கொள்","விழவர் ஓதை சிறந்துஆர்ப்ப","நடந்தாய் வாழி காவேரி.","விழவர் ஓதை சிறந்துஆர்ப்ப","நடந்த எல்லாம் வாய்காவா","மழவர் ஓதை வளவன்தன்","வளனே வாழி காவேரி.","வேறு (சார்த்து வரி - முகச்சார்த்து)","கரியமலர் நெடுங்கண் காரிகைமுன்                                                          ரு","கடல்தெய்வம் காட்டிக் காட்டி","அரியசூள் பொய்த்தார் அறன்இலர்என்று","ஏழையம்யாங்கு அறிகோம் ஐய","விரிகதிர் வெண்மதியும் மீன்கணமும்","ஆம்என்றே விளங்கும் வெள்ளைப்","புரிவளையும் முத்தும்கண்டு ஆம்பல்","பொதிஅவிழ்க்கும் புகாரே எம்மூர்.","காதலர் ஆகிக் கழிக்கானல்                                                                   Ü","கையுறைகொண்டு எம்பின் வந்தார்","ஏதிலர் தாமாகி யாம்இரப்ப","நிற்பதையாங்கு அறிகோம் ஐய","மாதரார் கண்ணும் மதிநிழல்நீர்","இணைகொண்டு மலர்ந்த நீலப்","போதும் அறியாது வண்டுஊச","லாடும் புகாரே எம்மூர்.","மோது முதுதிரையால் மொத்துண்டு                                                          எ","போந்துஅசைந்த முரல்வாய்ச் சங்கம்","மாதர் வரிமணல்மேல் வண்டல்","உழுதுஅழிப்ப மாழ்கி ஐய","கோதை பரிந்துஅசைய மெல்விரலால்","கொண்டுஓச்சும் குவளை மாலைப்","போது சிறங்கணிப்பப் போவார்கண்","போகாப் புகாரே எம்மூர்.","வேறு (முகம் இல் வரி)","துறைமேய் வலம்புரி தோய்ந்து மணல்உழுத                                      அ","தோற்றம் மாய்வான்","பொறைமலி பூம்புன்னைப் பூஉதிர்ந்து நுண்தாது","போர்க்கும் கானல்","நிறைமதி வாள்முகத்து நேர்க்கயல்கண் செய்த","உறைமலி உய்யாநோய் ஊர்சுணங்கு மென்முலையே","தீர்க்கும் போலும்.","(கானல் வரி)","நிணம்கொள் புலால்உணங்கல் நின்றுபுள் ஓப்புதல்","தலைக்கீடு ஆகக்","கணம்கொள் வண்டுஆர்த்து உலாம்கன்னி நறுஞாழல்","கையில் ஏந்தி","மணம்கமழ் பூங்கானல் மன்னிமற்று ஆண்டுஓர்","அணங்குஉறையும் என்பது அறியேன் அறிவேனேல்","அடையேன் மன்னோ.","வலைவாழ்நர் சேரி வலைஉணங்கும் முன்றில்                              க0","மலர்கை ஏந்தி","விலைமீன் உணங்கல் பொருட்டாக வேண்டுஉருவம்","கொண்டு வேறுஓர்","கொலைவேல் நெடுங்கண் கொடுங்கூற்றம் வாழ்வது","அலைநீர்த்தண் கானல் அறியேன் அறிவேனேல்","அடையேன் மன்னோ.","வேறு (நிலைவரி)","கயல்எழுதி வில்எழுதிக் கார்எழுதிக் காமன்                                         கக","செயல்எழுதித் தீர்ந்தமுகம் திங்களோ காணீர்.","திங்களோ காணீர் திமில்வாழ்நர் சீறூர்க்கே","அம்கண்ஏர் வானத்து அரவுஅஞ்சி வாழ்வதுவே.","எறிவளைகள் ஆர்ப்ப இருமருங்கும் ஓடும்                   கஉ","கறைகெழுவேல் கண்ணோ கடுங்கூற்றம் காணீர்.","கடுங்கூற்றம் காணீர் கடல்வாழ்நர் சீறூர்க்கே","மடம்கெழுமென் சாயல் மகளா யதுவே.","புலவுமீன் வெள்உணங்கல் புள்ஓப்பிக் கண்டார்க்கு                   க௩","அலவநோய் செய்யும் அணங்குஇதுவோ காணீர்.","அணங்குஇதுவோ காணீர் அடும்புஅமர்த்தண் கானல்","பிணங்குநேர் ஐம்பால்ஓர் பெண்கொண் டதுவே.","வேறு (முரிவரி)","பொழில்தரு நறுமலரே புதுமணம் விரிமணலே                               க௪","பழுதுஅறு திருமொழியே பணைஇள வனமுலையே","முழுமதி புரைமுகமே முரிபுரு வில்இணையே","எழுதுஅரு மின்இடையே எனைஇடர் செய்தவையே.","திரைவிரி தருதுறையே திருமணல் விரிஇடமே             கரு","விரைவிரி நறுமலரே மிடைதரு பொழில்இடமே","மருவிரி புரிகுழலே மதிபுரை திருமுகமே","இருகயல் இணைவிழியே எனைஇடர் செய்தவையே.","வளைவளர் தருதுறையே மணம்விரி தருபொழிலே                 கÜ","தளைஅவிழ் நறுமலரே தனிஅவள் திரிஇடமே","முளைவளர் இளநகையே முழுமதி புரைமுகமே","இளையவள் இணைமுலையே எனைஇடர் செய்தவையே.","வேறு (திணை நிலைவரி)","கடல்புக்கு உயிர்க்கொன்று வாழ்வர்நின் ஐயர்                                  கஎ","உடல்புக்கு உயிர்க்கொன்று வாழ்வைமன் நீயும்","மிடல்புக்கு அடங்காத வெம்முலையோ பாரம்","இடர்புக்கு இடுகும் இடைஇழவல் கண்டாய்.","கொடுங்கண் வலையால் உயிர்க்கொல்வான் நுந்தை        கஅ","நெடுங்கண் வலையால் உயிர்க்கொல்வை மன்நீயும்","வடம்கொள் முலையால் மழைமின்னுப் போல","நுடங்கி உகுமென் நுசுப்புஇழவல் காண்டாய்.","ஓடும் திமில்கொண்டு உயிர்க்கொள்வர் நின்ஐயர்","கோடும் புருவத்து உயிர்க்கொல்வை மன்நீயும்                     க௯","பீடும் பிறர்எவ்வம் பாராய் முலைசுமந்து","வாடும் சிறுமென் மருங்குஇழவல் கண்டாய்.","வேறு","பவள உலக்கை கையால் பற்றித்                                                        உ0","தவள முத்தம் குறுவாள் செங்கண்","தவள முத்தங் குறுவாள் செங்கண்","குவளை அல்ல கொடிய கொடிய","புன்னை நீழல் புலவுத் திரைவாய்                        உக","அன்னம் நடப்ப நடப்பாள் செங்கண்","அன்னம் நடப்ப நடப்பாள் செங்கண்","கொன்னே வெய்ய. கூற்றம் கூற்றம்.","கள்வாய் நீலம் கையின் ஏந்திப்                                                           உஉ","புள்வாய் உணங்கல் கடிவாள் செங்கண்","புள்வாய் உணங்கல் கடிவாள் செங்கண்","வெள்வேல் அல்ல. வெய்ய வெய்ய.","வேறு","சேரல் மடஅன்னம் சேரல் நடைஒவ்வாய்                                    உ௩","சேரல் மடஅன்னம் சேரல் நடைஒவ்வாய்","ஊர்திரை நீர்வேலி உழக்கித் திரிவாள்பின்","சேரல் மடஅன்னம் சேரல் நடைஒவ்வாய்.","(கட்டுரை)","ஆங்கு, கானல்வரிப் பாடல்கேட்ட                                                      உ௪","மான்நெடுங்கண் மாதவியும்","மன்னும்ஓர் குறிப்புஉண்டுஇவன்","தன்நிலை மயங்கினான்எனக்","கலவியால் மகிழ்ந்தாள்போல்","புலவியால் யாழ்வாங்கித்","தானும்ஓர் குறிப்பினள்போல்","கானல்வரிப் பாடல்பாணி","நிலத்தெய்வம் வியப்புஎய்த","நீள்நிலத்தோர் மனம்மகிழக்","கலத்தொடு புணர்ந்துஅமைந்த","கண்டத்தால் பாடத்தொடங்கும்மன்.","வேறு (ஆற்று வரி)","மருங்கு வண்டு சிறந்துஆர்ப்ப                                                          உரு","மணிப்பூ ஆடை அதுபோர்த்துக்","கருங்க யல்கண் விழித்துஒல்கி","நடந்தாய் வாழி காவேரி.","கருங்க யல்கண் விழித்துஒல்கி","நடந்த எல்லாம் நின்கணவன்","திருந்து செங்கோல் வளையாமை","அறிந்தேன் வாழி காவேரி.","பூவர் சோலை மயில்ஆலப்                                                             உÜ","புரிந்து குயில்கள் இசைபாடக்","காமர் மாலை அருகுஅசைய","நடந்தாய் வாழி காவேரி.","காமர் மாலை அருகுஅசைய","நடந்த எல்லாம் நின்கணவன்","நாம வேலின் திறம்கண்டே","அறிந்தேன் வாழி காவேரி.","வாழி அவன்தன் வளநாடு                                                                உஎ","மகவாய் வளர்க்கும் தாய்ஆகி","ஊழி உய்க்கும் பேர்உதவி","ஒழியாய் வாழி காவேரி.","ஊழி உய்க்கும் பேர்உதவி","ஒழியாது ஒழுகல் உயிர்ஓம்பும்","ஆழி ஆள்வான் பகல்வெய்யோன்","அருளே வாழி காவேரி.","வேறு (சார்த்து வரி)","தீங்கதிர் வாள்முகத்தாள் செவ்வாய் மணிமுறுவல் ஒவ்வா வேனும்                                  உஅ","வாங்கும்நீர் முத்துஎன்று வைகலும் மால்மகன்போல் வருதிர் ஐய","வீங்குஓதம் தந்து விளங்குஒளிய வெண்முத்தம் விரைசூழ் கானல்","பூங்கோதை கொண்டு விலைஞர்போல் மீளும் புகாரே எம்மூர்.","மறையின் மணந்தாரை வன்பரதர் பாக்கத்து மடவார் செங்கை உ௯","இறைவளைகள் தூற்றுவதை ஏழையம் எங்ஙனம்யாங்கு அறிகோம் ஐய","நிறைமதியும் மீனும் எனஅன்னம் நீள்புன்னை அரும்பிப் பூத்த","பொறைமலிபூங் கொம்புஏற வண்டுஆம்பல் ஊதும் புகாரே எம்மூர்.","உண்டாரை வெல்நறா ஊண்ஓழியாப் பாக்கத்துள் உறைஒன்று இன்றித்","தண்டாநோய் மாதர் தலைத்தருதி என்பதுயாங்கு அறிகோம் ஐய","வண்டல் திரைஅழிப்பக் கையால் மணல்முகந்து மதிமேல் நீண்ட","புண்தோய்வேல் நீர்மல்க பரதர் கடல்து஡ர்க்கும் புகாரே எம்மூர்.","வேறு (திணை நிலைவரி)","புணர்த்துணையோடு ஆடும் பொறிஅலவன் நோக்கி                        ௩க","இணர்த்ததையும் பூங்கானல் என்னையும் நோக்கி","உணர்வுஒழியப் போன ஒலிதிரைநீர்ச் சேர்ப்பன்","வணர்சுரி ஐம்பாலோய் வண்ணம் உணரேனால்.","தம்முடைய தண்ணளியும் தாமும்தம் மான்தேரும்                         ௩உ","எம்மை நினையாது விட்டாரோ விட்டுஅகல்க","அம்மென் இணர அடும்புகாள் அன்னங்காள்","நம்மை மறந்தாரை நாம்மறக்க மாட்டேமால்.","புன்கண்கூர் மாலைப் புலம்பும்என் கண்ணேபோல்","துன்பம் உழவாய் துயிலப் பெறுதியால்","இன்கள்வாய் நெய்தால்நீ எய்தும் கனவினுள்","வன்கணார் கானல் வரக்கண்டு அறிதியோ?","புள்இயல்மான் தேர்ஆழி போன வழிஎல்லாம்","தெள்ளுநீர் ஓதம் சிதைத்தாய்மற்று எஞ்செய்கோ?","தெள்ளுநீர் ஓதம் சிதைத்தாய்மற்று எம்மோடுஈங்கு","உள்ளாரோடு உள்ளாய் உணராய்மற்று எஞ்செய்கோ?","நேர்ந்தநம் காதலர் நேமிநெடுந் திண்தேர்                    ௩ரு","ஊர்ந்த வழிசிதைய ஊர்க்கின்ற ஓதமே","பூந்தண் பொழிலே புணர்ந்துஆடும் அன்னமே","ஈர்ந்தண் துறையே இதுதகாது என்னீரே.","நேர்ந்தநம் காதலர் நேமிநெடுந் திண்தேர்                   ௩Ü","ஊர்ந்த வழிசிதைய ஊர்ந்தாய்வாழி கடல்ஓதம்","ஊர்ந்த வழிசிதைய ஊர்ந்தாய்மற்(று) எம்மொடு","தீர்ந்தாய்போல் தீர்ந்திலையால் வாழி கடல்ஓதம்.","வேறு (மயங்கு திணை நிலைவரி)","நன்நித் திலத்தின் பூண்அணிந்து","நலம்சார் பவளக் கலைஉடுத்துச்                                                             ௩எ","செந்நெல் பழனக் கழனிதொறும்","திரைஉ லாவு கடல்சேர்ப்ப.","புன்னைப் பொதும்பர் மகரத்திண்","கொடியோன் எய்த புதுப்புண்கள்","என்னைக் காணா வகைமறத்தால்","அன்னை காணின் என்செய்கோ?","வாரித் தரள நகைசெய்து","வண்செம் பவள வாய்மலர்ந்து                                                                 ௩அ","சேரிப் பரதர் வலைமுன்றில்","திரைஉ லாவு கடல்சேர்ப்ப.","மாரிப் பீரத்து அலர்வண்ணம்","மடவாள் கொள்ளக் கடவுள்வரைந்து","ஆர்இக் கொடுமை செய்தார்என்று","அன்னை அறியின் என்செய்கோ?","புலவுற்று இரங்கி அதுநீங்கப்","பொழில்தண் டலையில் புகுந்துஉதிர்ந்த","கலவைச் செம்மல் மணம்கமழத்","திரைஉ லாவு கடல்சேர்ப்ப.","பலஉற்று ஒருநோய் திணியாத","படர்நோய் மடவாள் தனிஉழப்ப","அலவுற்று இரங்கி அறியாநோய்","அன்னை அறியின் என்செய்கோ?","வேறு","இளைஇருள் பரந்ததுவே எல்செய்வான் மறைந்தனனே","களைவுஅரும் புலம்புநீர் கண்பொழீஇ உகுத்தனவே","தளைஅவிழ் மலர்க்குழலாய் தணந்தார்நாட்டு உளதாம்கொல்","வளைநெகிழ எரிசிந்தி வந்தஇம் மருள்மாலை?","கதிரவன் மறைந்தனனே கார்இருள் பரந்ததுவே                                  ௪க","எதிர்மலர் புரைஉண்கண் எவ்வநீர் உகுத்தனவே","புதுமதி புரைமுகத்தாய் போனார்நாட்டு உளதாம்கொல்","மதிஉமிழ்ந்து கதிர்விழுங்கி வந்தஇம் மருள்மாலை?","பறவைபாட்டு அடங்கினவே பகல்செய்வான் மறைந்தனனே   ௪உ","நிறைநிலா நோய்கூர நெடுங்கண்நீர் உகுத்தனவே","துறுமலர் அவிழ்குழலாய் துறந்தார்நாட்டு உளதாம்கொல்","மறவையாய் என்உயிர்மேல் வந்தஇம் மருள்மாலை?","வேறு (சாயல் வரி)","கைதை வேலிக் கழிவாய் வந்துஎம்","பொய்தல் அழித்துப் போனார் ஒருவர்","பொய்தல் அழித்துப் போனார் அவர்நம்","மையல் மனம்விட்டு அகல்வார் அல்லர்.","கானல் வேலிக் கழிவாய் வந்து","நீநல்கு என்றே நின்றார் ஒருவர்","நீநல்கு என்றே நின்றார் அவர்நம்","மான்நேர் நோக்கம் மறப்பார் அல்லர்.","அன்னம் துணையோடு ஆடக் கண்டு                        ௪ரு","நென்னல் நோக்கி நின்றார் ஒருவர்","நென்னல் நோக்கி நின்றார் அவர்நம்","பொன்நேர் சுணங்கிற் போவார் அல்லர்.","வேறு (முகம் இல் வரி)","அடையல் குருகே அடையல்எம் கானல்                    ௪ Ü","அடையல் குருகே அடையல்எம் கானல்","உடைதிரைநீர்ச் சேர்ப்பற்கு உறுநோய் உரையாய்","அடையல் குருகே அடையல்எம் கானல்.","வேறு (காடுரை)","ஆங்கனம் பாடிய ஆயிழை பின்னரும்                                                  ௪எ","காந்தள் மெல்விரல் கைக்கிளை சேர்குரல்","தீந்தொடைச் செவ்வழிப் பாலை இசைஎழீஇப்","பாங்கினில் பாடிஓர் பண்ணும் பெயர்த்தாள்.","வேறு (முகம் இல் வரி)","நுளையர் விளரி நொடிதரும்தீம் பாலை                                              ௪அ","இளிகிளையில் கொள்ள இறுத்தாயால் மாலை","இளிகிளையில் கொள்ள இறுத்தாய்மன் நீயேல்","கொளைவல்லாய் என்ஆவி கொள்வாழி மாலை.","பிரிந்தார் பரிந்துஉரைத்த பேர்அருளின் நீழல்","இருந்துஏங்கி வாழ்வார் உயிர்ப்புறத்தாய் மாலை","உயிர்ப்புறத்தாய் நீஆகில் உள்ஆற்றா வேந்தன்","எயில்புறத்து வேந்தனோடு என்ஆதி மாலை.","பையுள்நோய் கூரப் பகல்செய்வான் போய்வீழ              ரு0","வையமோ கண்புதைப்ப வந்தாய் மருள்மாலை","மாலைநீ ஆயின் மணந்தார் அவர்ஆயின்","ஞாலமோ நல்கூர்ந் ததுவாழி மாலை.","வேறு (கட்டுரை)","தீத்துழைஇ வந்தஇச் செல்வன் மருள்மாலை                ருக","தூக்காது துணிந்தஇத் துயரெஞ்ச் கிளவியால்","பூககமழ் கானலிற் பொய்ச்சூள் பொறுக்கென்று","மாக்கடற் றெய்வநின் மலரடி வணங்குதும்","எனக்கேட்டு,                                                                                                       ருஉ","கானல்வரி யான்பாடத் தான்ஒன்றின்மேல் மனம்வைத்து","மாயப்பொய் பலகூட்டும் மாயத்தாள் பாடினாள்என","யாழ்இசைமேல் வைத்துத்தன் ஊழ்வினைவந்து உருத்ததுஆகலின்","உவவுஉற்ற திங்கள்முகத்தாளைக் கவவுக்கை ஞெகிழ்ந்தனனாய்ப்","பொழுதுஈங்குக் கழிந்ததுஆகலின் எழுதும்என்று உடன்எழாது","ஏவலாளர் உடஞ்சூழக் கோவலன்தான் போனபின்னர்,","தாதுஅவிழ் மலர்ச்சோலை ஓதைஆயத்து ஒலிஅவித்துக்","கையற்ற நெஞ்சினளாய் வையத்தி னுள்புக்குக்","காதலனுடன் அன்றியே மாதவிதன் மனைபுக்காள்","ஆங்கு,","மாயிரு ஞாலத்து அரசு தலைவணக்கும்","சூழி யானைச் சுடர்வாள் செம்பியன்","மாலை வெண்குடை கவிப்ப","ஆழி மால்வரை அகவையா எனவே.","நாவலர் பண்டித ந.மு. வேங்கடசாமி நாட்டாரவர்கள் உரை","கட்டுரை","௧. சித்திரப் படத்துள்புக்குச் செழுங்கோட்டின் மலர்புனைந்து மைத்தடங்கண் மணமகளிர் கோலம்போல் வனப்புஎய்திப்","பத்தரும் கோடும் ஆணியும் நரம்பும்என்று இத்திறத்துக் குற்றம்நீங்கிய யாழ்கையில் தொழுதுவாங்கி","பண்ணல் பரிவட்டணை ஆராய்தல் தைவரல் கண்ணிய செலவு விளையாட்டுக் கையூழ் நண்ணிய குறும்போக்கு என்று நாட்டிய எண்வகையால் இசைஎழீஇப் பண்வகையால் பரிவுதீர்ந்து","மரகதமணித் தாள்செறிந்த மணிக்காந்தள் மெல்விரல்கள்","பயிர்வண்டின் கிளைபோலப் பல்நரம்பின் மிசைப்படர வார்தல் வடித்தல் உந்தல் உறழ்தல்","சீருடன் உருட்டல் தெருட்டல் அள்ளல் ஏர்உடைப் பட்டடைஎன இசையோர் வகுத்த","எட்டு வகையின் இசைக்கர ணத்துப் பட்டவகைதன் செவியின்ஓர்த்து","ஏவலன், பின் பாணி யாதுஎனக் கோவலன் கையாழ் நீட்ட, அவனும்","காவிரியை நோக்கினவும் கடல்கானல் வரிப்பாணியும் மாதவிதன் மனம்மகிழ வாசித்தல் தொடங்குமன்.","சித்திரப் படத்துள் புக்கு – சித்திரத் தொழிலமைந்த ஆடையுட் புகுந்து, செழுங்கோட்டில் மலர் புனைந்து-அழகிய கோட்டிலே மலர் சூடி, மைத்தடங்கண் மண மகளிர் கோலம் போல் வனப்பு எய்தி-மை தீற்றிய பெரிய கண்களையுடைய மணமகளின் ஒப்பனைக் கோலம்போல் அழகினைப் பொருந்தி, பத்தரும் கோடும் ஆணியும் நரம்பும் என்று இத்திறத்துக் குற்றம் நீங்கிய-பத்தர் கோடு ஆணி நரம்பு என்ற இவ்வகை உறுப்புக்களின் குற்றம் ஒழிந்த, யாழ்-யாழினை, கையில் தொழுது வாங்கி-கும்பிட்டுக் கையில் வாங்கி,பண்ணல் பரிவட்டணை ஆராய்தல் தைவரல் (கண்ணிய) செலவு விளையாட்டுக் கையூழ் (நண்ணிய) குறும் போக்கு என்று நாட்டிய எண் வகையால் இசை எழீஇ-பண்ணல் முதலாக நிறுத்தப்பட்ட எட்டுவகைக் கலைத் தொழிலானும் இசையை எழுப்பி, பண் வகையாற் பரிவு தீர்ந்து-பண்வகையிற் குற்றம் நீங்கி, மரகத மணித்தாள் செறிந்த மணிக்காந்தள் மெல் விரல்கள்-மரகதமணி மோதிரங்கள் செறிந்த அழகிய காந்தளிதழ் போலும் மெல்லிய விரல்கள், பயிர் வண்டின் கிளைபோலப் பல் நரம்பின் மிசைப்படா-பாடுகின்ற வண்டின் இனம்போலப் பலவாகிய நரம்பின் மீதே செல்ல, வார்தல் வடித்தல் உந்தல் உறழ்தல் (சீருடன்) உருட்டல் தெருட்டல் அள்ளல் (ஏருடைப்) பட்டடை என இசையோர் வகுத்த எட்டு வகையின் இசைக் காணத்து – வார்தல் முதலாக இசைநூலோரால் வகுக்கப் பட்ட எட்டுவகை இசைக் கரணத்தாலும், பட்டவகை தன் செவியின் ஓர்த்து-உண்டாகிய இசையின் கூறுபாட்டைத் தன் செவியாலே சீர் தூக்கி யறிந்து, ஏவலன் பின் பாணியாது எனக் கோவலன் கையாழ் நீட்ட-ஏவினபடி செய்தற்குரியேன் மேல் நுமது பணி யாதென்று கூறிக் கோவலன் கையிலே அவ்வியாழை நீட்ட, அவனும் காவிரியை நோக்கினவும் கடற் கானல் வரிப் பாணியும் மாதவி தன் மனம் மகிழ வாசித்தல் தொடங்கும் மன்-அவன் காவிரியைக் கருதியனவும் கடற் கானலைக் கருதியனவுமாகிய வரிப்பாட்டுக்களை மாதவியின் மனம் மகிழும்படி வாசிக்கத் தொடங்கினான்.","படம்-ஆடை. அதனாலாய உறை. சித்திரப் படத்துட் புக்கமையாலும் மலர் புனைந்தமையாலும் மணமகள் போன்றது.  \"மணங்கமழ் மாதரை மண்ணி யன்ன\"என்றார் பிறரும். கோடு-யாழின் தண்டு. பத்தர் முதலிய நான்கும் யாழின் உறுப்புக்கள். இவையன்றி மாடகம் எனப்படும் முறுக்காணியும். திவவு எனப்படும் வார்க்கட்டும் யாழுறுப்புக்களாம். குற்றமற்ற மரத்தாற் செய்த பத்தர் முதலாயினவும் கொடும்புரி, மயிரி, தும்பு முறுக்கு என்பன இல்லாத நரம்பும் உடைய யாழென்பார். \"இத்திறத்துக் குற்ற நீங்கிய யாழ் \"என்றார். மரத்தின் குற்றமாவன வெயிலும் காற்றும் நீரும் நிழலும் மிகுதல். திருத்தக்கதேவர்  \"நோய் நன்கு நீங்கி\" என்றருளியதும், அதற்கு நச்சினார்க்கினியர் எழுதிய உரையும் நோக்குக. மற்றும் அவர், பொருநராற்றுப்படை யுரையில் \"கொன்றை கருங்காலி குமிழ் முருக்குத் தணக்கே\"என்பதனால் கோட்டிற்கு மரம் கொன்றையும் கருங்காலியுமாம்; பத்தர்க்குக் குமிழும் முருக்கும் தணக்குமாம்\" என்றெழுதியதும் ஈண்டு அறியற்பாலது. \"கொடும்புரி மயிர் தும்பு முருக்கிவை நான்கும் நடுங்கா மரபிற் பகையென மொழிப\"என்றதனால் நரம்பின் குற்றம் அறிக. யாழினிடத்தே தெய்வம் உறைதலின் அதனைத் தொழுது வாங்கினாள்.  \"அணங்கு மெய்ந்நின்ற அமைவரு காட்சி\"என்பது காண்க.  \"பண்ணல்- பாடநினைத்த பண்ணுக்கு இணை கிளை பகை நட்பான நரம்புகள் பெயருந்தன்மை மாத்திரை அறிந்து வீக்குதல்; பரிவட்டணை-அவ்வீக்கின நரம்பை அகவிரலாலும் புறவிரலாலும் கரணஞ் செய்து தடவிப் பார்த்தல். ஆராய்தல்-ஆரோகண அவரோகண வகையால் இசையைத் தெரிவது; அநுசுருதி யேற்றுதல், தைவரல்; ஆளத்தியிலே நிரம்பப் பாடுதல், செலவு; பாட நினைத்த வண்ணத்திற் சந்தத்தை விடுதல் விளையாட்டு. வண்ணத்திற் செய்த பாடலெல்லாம் இன்பமாகப் பாடுதல் கையூழ். சூடகச் செலவும் துள்ளற் செலவும் பாடுதல் குறும்போக்கு\"என்பது சிந்தாமணி நச்சினார்க்கினியம்.இவற்றிற்கு அரும்பதவுரையாசிரியர் காட்டிய சூத்திரங்கள் பின் வருவன:","௧.\t \"வலக்கைப் பெருவிரல் குரல்கொளச் சிறுவிரல்","விலக்கின் றிளிவழி கேட்டும்","இணைவழி யாராய்ந் திணைகொள முடிப்பது","விளைப்பரு மரபிற் பண்ண லாகும்\".","௨.\t\"பரிவட்ட ணையி னிலக்கணந் தானே","மூவகை நடையின் முடிவிற் றாகி","வலக்கை யிருவிரல் வனப்புறத் தழீஇ","இடக்கை விரலி னியைவ தாகத்","தொடையொடு தோன்றியுந் தோன்றா தாகியும்","நடையொடு தோன்றும் நயத்த தாகும்.\"","௩.\t\"ஆராய்த லென்ப தமைவரக் கிளப்பிற்","குரன்முத லாக விணைவழி கேட்டும்","இணையி லாவழிப் பயனொடு கேட்டும்","தாரமு முழையுந் தம்மிற் கேட்டும்","குரலு மிளியுந் தம்மிற் கேட்டும்","துத்தமும் விளரியுந் துன்னுறக் கேட்டும்","விளரி-கைக்கிளை விதியுளிக் கேட்டும்","தளரா தாகிய தன்மைத் தாகும்.\"","௪.\t\"தைவர லென்பது சாற்றுங் காலை","மையறு சிறப்பின் மனமகிழ் வெய்தித்","தொடையொடு பட்டும் படாஅ தாகியும்","நடையொடு தோன்றி யாப்புநடை யின்றி","ஓவச் செய்தியின் வட்டணை யொழுகிச்","சீரேற் றியன்று மியலா தாகியும்","நீர வாகு நிறைய தென்ப.\"","௫.\t\"செலவெனப் படுவதன் செய்கை தானே","பாலை பண்ணே திறமே கூடமென","நால்வகை யிடத்து நயத்த தாகி","இயக்கமு நடையு மெய்திய வகைத்தாய்ப்","பதினோ ராடலும் பாணியு மியல்பும்","விதிநான்கு தொடர்ந்து விளங்கிச் செல்வதுவே.\"","௬.\t\"விளையாட் டென்பது விரிக்குங் காலைக்","கிளவிய வகையி னெழுவகை யெழாலும்","அளவிய தகைய தாகு மென்ப.\"","௭.\t\"கையூ ழென்பது கருதுங் காலை","எவ்விடத் தானு மின்பமுஞ் சுவையும்","செவ்விதிற் றோன்றிச் சிலைத்துவர லின்றி","நடைநிலை திரியாது நண்ணித் தோன்றி","நாற்பத் தொன்பது வனப்பும் வண்ணமும்","பாற்படத் தோன்றும் பகுதித் தாகும்.\"","௮.\t\"துள்ளற் கண்ணுங் குடக்குத் துள்ளும்","தள்ளா தாகிய உடனிலைப் புணர்ச்சி","கொள்வன வெல்லாங் குறும்போக் காகும்.\""],"english":null,"url":""}},{"ta":"மணிமேகலை","en":"Manimekalai 00.010","note":"2nd–6th century CE","verse":{"id":"MANI-0001","text":"Manimekalai","textTa":"மணிமேகலை","number":"00.010","lines":["இளங் கதிர் ஞாயிறு எள்ளும் தோற்றத்து","விளங்கு ஒளி மேனி விரி சடையாட்டி","பொன் திகழ் நெடு வரை உச்சித் தோன்றி","தென் திசைப் பெயர்ந்த இத் தீவத் தெய்வதம்","சாகைச் சம்பு தன் கீழ் நின்று","மா நில மடந்தைக்கு வரும் துயர் கேட்டு","வெந் திறல் அரக்கர்க்கு வெம் பகை நோற்ற","சம்பு என்பாள் சம்பாபதியினள்","செங்கதிர்ச் செல்வன் திருக் குலம் விளக்கும்","கஞ்ச வேட்கையின் காந்த மன் வேண்ட"],"english":null,"url":""}},{"ta":"மணிமேகலை","en":"Manimekalai 13.090","note":"2nd–6th century CE","verse":{"id":"MANI-0165","text":"Manimekalai","textTa":"மணிமேகலை","number":"13.090","lines":["காப்புக் கடைகழிந்து கணவனை இகழ்ந்தேன்","எறி பயம் உடைமையின் இரியல் மாக்களொடு","தெற்கண் குமரி ஆடிய வருவேன்","பொன் தேர்ச் செழியன் கொற்கை அம் பேர் ஊர்க்","காவதம் கடந்து கோவலர் இருக்கையின்","ஈன்ற குழவிக்கு இரங்கேனாகித்","தோன்றாத் துடவையின் இட்டனன் போந்தேன்","செல் கதி உண்டோ தீவினையேற்கு?'' என்று","அல்லல் உற்று அழுத அவள் மகன் ஈங்கு இவன்","சொல்லுதல் தேற்றேன் சொல் பயம் இன்மையின்"],"english":null,"url":""}},{"ta":"மணிமேகலை","en":"Manimekalai 24.150","note":"2nd–6th century CE","verse":{"id":"MANI-0329","text":"Manimekalai","textTa":"மணிமேகலை","number":"24.150","lines":["அரைசன் தேவியொடு ஆய் இழை நல்லீர்!","புரை தீர் நல் அறம் போற்றிக் கேண்மின்","மறு பிறப்பு உணர்ந்த மணிமேகலை நீ!","பிற அறம் கேட்ட பின் நாள் வந்து உனக்கு","இத் திறம் பலவும் இவற்றின் பகுதியும்","முத்து ஏர் நகையாய்! முன்னுறக் கூறுவல்''","என்று அவன் எழுதலும் இளங்கொடி எழுந்து","நன்று அறி மாதவன் நல் அடி வணங்கி","''தேவியும் ஆயமும் சித்திராபதியும்","மாதவர் நல் மொழி மறவாது உய்ம்மின்"],"english":null,"url":""}}]'::jsonb, 11, true, '{"step_count":6}'::jsonb)
