  ('grammar-terms', 'grammar', null, 'quiz', 'Grammar Master', 'Match each Tolkāppiyam term to its meaning.', '/challenges/desk.webp', 5, 27, 15, 'Solveli ontology', 5, true, '{}'::jsonb),
  ('grammar-books', 'grammar', null, 'world', 'Three Athikārams', 'Letters, words or subject matter? Place the sūtra in its book.', '/challenges/books.webp', 5, 45, 15, 'Tolkāppiyam · Project Madurai', 6, true, '{}'::jsonb),
  ('twin-epics', 'history', null, 'world', 'Twin Epics', 'Cilappatikāram or Maṇimēkalai? Recognise the epic.', '/challenges/ships.webp', 5, 20, 15, 'Sentamizh corpus · Project Madurai', 7, true, '{}'::jsonb)
insert into public.guides (id, name, name_ta, category, era, sort_order, tags, world_id, glyph, image, bio, poet_names, active) values
  ('thiruvalluvar', 'Thiruvalluvar', 'திருவள்ளுவர்', 'philosophers', 'c. 300–600 CE (contested)', 40, array['Ethics', 'Life', 'Humanity']::text[], 'thirukkural', 'வ', '/challenges/kural.webp', 'Author of the Tirukkuṟaḷ: 1,330 couplets in 133 chapters on virtue (aṟam), wealth (poruḷ) and love (iṉpam). Almost nothing certain is known of his life; the work itself is his portrait.', '{}'::text[], true),
  ('avvaiyar', 'Avvaiyar', 'ஔவையார்', 'sangam', 'Sangam age · and later poets of the name', 20, array['Wisdom', 'Morality', 'Education']::text[], 'sangam', 'ஔ', '/lessons/temple.webp', '“Avvaiyar” names more than one poet. The Sangam Avvaiyar''s poems appear in the anthologies, including Kuṟuntokai; the short moral verses of the Āttichūḍi are attributed to a later Avvaiyar.', array['ஔவையார்']::text[], true),
  ('kapilar', 'Kapilar', 'கபிலர்', 'sangam', 'Sangam age', 21, array['Kuṟiñci', 'Nature', 'Friendship']::text[], 'sangam', 'க', '/lessons/kurinji.webp', 'One of the most prolific Sangam poets, remembered especially for kuṟiñci — poems of the mountain landscape and lovers'' union.', array['கபிலர்']::text[], true),
  ('paranar', 'Paranar', 'பரணர்', 'sangam', 'Sangam age', 22, array['History', 'Akam', 'Puṟam']::text[], 'sangam', 'ப', '/lessons/coast.webp', 'Sangam poet whose verses weave references to kings, battles and places into both love poetry and heroic poetry.', array['பரணர்']::text[], true),
  ('nakkirar', 'Nakkīrar', 'நக்கீரர்', 'sangam', 'Sangam age', 23, array['Poetry', 'Truth', 'Criticism']::text[], 'sangam', 'ந', '/worlds/sangam.webp', 'Sangam poet of Madurai, whose name tradition links with fearless literary judgement. The anthologies preserve poems under forms of his name (நக்கீரர், நக்கீரனார்).', array['நக்கீர']::text[], true),
  ('tolkappiyar', 'Tolkappiyar', 'தொல்காப்பியர்', 'grammarians', 'dating contested', 10, array['Grammar', 'Language', 'Poetics']::text[], 'grammar', 'தொ', '/lessons/books.webp', 'Author of the Tolkāppiyam, the oldest extant Tamil grammar, in three books: letters (Eḻuttu), words (Col) and subject matter (Poruḷ) — including the thiṇai landscapes of love poetry.', '{}'::text[], true),
  ('sambandar', 'Tirujñāna Sambandar', 'திருஞானசம்பந்தர்', 'bhakti', '7th century CE', 60, array['Devotion', 'Music', 'Śaiva']::text[], 'bhakti', 'ச', '/lessons/deity.webp', 'Śaiva poet-saint and one of the three poets of the Tēvāram; the first three books of the Tirumuṟai are his hymns, sung to the shrines of Tamil country.', array['Sambandar']::text[], true),
  ('andal', 'Andal', 'ஆண்டாள்', 'bhakti', '8th century CE', 65, array['Devotion', 'Love', 'Vaiṣṇava']::text[], 'bhakti', 'ஆ', '/challenges/temple.webp', 'The only woman among the twelve Āḻvārs. Her Tiruppāvai and Nācciyār Tirumoḻi are part of the Nālāyira Divya Prabandham.', array['ஆண்டாள்']::text[], true),
  ('ilango', 'Ilango Adigal', 'இளங்கோ அடிகள்', 'epic', 'c. 5th–6th century CE (contested)', 50, array['Epic', 'Justice', 'Society']::text[], 'history', 'இ', '/lessons/harbor.webp', 'Traditionally the author of Cilappatikāram, the epic of Kaṇṇaki and Kōvalaṉ that moves across the Chola, Pandya and Chera countries.', '{}'::text[], true),
  ('sattanar', 'Cīttalai Cāttaṉār', 'சீத்தலைச் சாத்தனார்', 'epic', 'c. 6th century CE (contested)', 51, array['Epic', 'Ethics', 'Buddhism']::text[], 'history', 'சா', '/challenges/ships.webp', 'Traditionally the author of Maṇimēkalai, the twin epic to Cilappatikāram, following Kōvalaṉ''s daughter into Buddhist renunciation.', '{}'::text[], true),
  ('kambar', 'Kambar', 'கம்பர்', 'epic', '12th century CE', 80, array['Epic', 'Poetry', 'Devotion']::text[], 'history', 'க', '/challenges/city.webp', 'Author of the Kamparāmāyaṇam, the Tamil telling of the Rāmāyaṇa. His works are not yet in Solveli''s corpus.', '{}'::text[], true),
  ('uvsa', 'U. V. Swaminatha Iyer', 'உ. வே. சாமிநாத ஐயர்', 'modern', '1855–1942', 100, array['Manuscripts', 'Editions', 'Preservation']::text[], 'sangam', 'உ', '/lessons/desk.webp', 'Scholar who searched out palm-leaf manuscripts and published the first printed editions of many classical works, among them Cilappatikāram, Maṇimēkalai and Sangam anthologies. Much of what Solveli can show survives through such editions.', '{}'::text[], true)
