  ('divya-prabandham', 'Divya Prabandham', 'திவ்ய பிரபந்தம்', 'Bhakti', '5th–10th century CE', 'Nalayira Divya Prabandham — Vaishnavite devotional hymns by the 12 Alvars', 'verses', 3928, 'bhakti', '{}'::text[], 'Sentamizh corpus (Apache-2.0)', 'available', '{}'::jsonb),
