  ('thirumanthiram', 'Thirumanthiram', 'திருமந்திரம்', 'Spiritual', '6th–10th century CE', 'Tenth Thirumurai by Tirumular on yoga, tantra, devotion, and metaphysics', 'verses', 335, 'bhakti', '{}'::text[], 'Sentamizh corpus (Apache-2.0)', 'available', '{}'::jsonb),
  ('tirukkural', 'Tirukkural', 'திருக்குறள்', 'Didactic', 'c. 300–600 CE (dating contested)', 'Thiruvalluvar''s 1330 couplets on virtue, wealth and love (1300 present in the provided PDF)', 'kurals', 1300, 'thirukkural', array['Thiruvalluvar']::text[], 'datasets/Thirukkural.pdf', 'available', '{}'::jsonb),
  ('tolkappiyam', 'Tolkappiyam', 'தொல்காப்பியம்', 'Grammar', 'dating contested', 'The oldest extant Tamil grammar: letters, words and poetic subject matter.', 'sūtras', 1598, 'grammar', array['Tolkappiyar']::text[], 'Project Madurai', 'available', '{}'::jsonb)
