insert into public.community_posts (slug, author_id, is_official, topic_id, title, body, tags, ref_label, ref_href, created_at) values
  ('p-anbu-72', null, true, 'discussions', 'What does அன்பு mean in Kural 72?', '“அன்பிலார் எல்லாம் தமக்குரியர்” — the loveless keep everything for themselves. Open the word view from the kural and compare the dictionary sense with the kural''s own meaning. Where do they differ?', array['Thirukkural', 'அன்பு', 'Context']::text[], 'Explore அன்பு in Kural 72', '/academy/search?q=அன்பிலார்&ctx=KURAL-72', '2026-09-01T09:00:00.000Z'),
  ('p-kelir-192', null, true, 'discussions', 'யாதும் ஊரே யாவரும் கேளிர் — every town is ours, everyone our kin', 'Puṟanāṉūṟu 192 is quoted everywhere. Read the whole poem: what does the rest of it say about fate, good and evil? Tap கேளிர் to see where else the word lives.', array['Purananuru', 'Sangam', 'கேளிர்']::text[], 'Read Puṟanāṉūṟu 192', '/academy/verse/PURN-192', '2026-09-01T09:00:00.000Z'),
  ('p-kuru-40', null, true, 'questions', 'Why is Kuṟuntokai 40 a kuṟiñci poem?', '“யாயும் ஞாயும் யார் ஆகியரோ” — my mother and yours, what are they to each other? The corpus tags this verse kuṟiñci (union). Which lines tell you that?', array['Kuruntokai', 'Kurinji', 'Thinai']::text[], 'Read Kuṟuntokai 40', '/academy/verse/KURU-040', '2026-09-01T09:00:00.000Z'),
  ('p-ezhuthu', null, true, 'questions', 'Uyir Ezhuthu or Mei Ezhuthu — how would you explain the difference?', 'Tolkāppiyam begins with letters. Try explaining vowels (உயிர்), consonants (மெய்) and their combinations (உயிர்மெய்) with one example of each.', array['Tolkappiyam', 'Grammar', 'Ezhuthu']::text[], 'Lesson: Letters — Eḻuttu', '/academy/lessons/ezhuthu', '2026-09-01T09:00:00.000Z'),
  ('p-kalvi', null, true, 'study', 'Study circle: Chapter 40, Learning (கல்வி)', 'Ten kurals, one theme. Read one a day with its three commentaries, and note which commentator you find clearest.', array['Thirukkural', 'கல்வி', 'Chapter 40']::text[], 'Lesson: Learning — Chapter 40', '/academy/lessons/kural-learning', '2026-09-01T09:00:00.000Z'),
  ('p-thinai', null, true, 'study', 'Study circle: the five thiṇai', 'Mountain, forest, farmland, seashore, desert. Take the lesson, then the “Name the Landscape” challenge — which thiṇai is hardest to recognise?', array['Sangam', 'Thinai', 'Landscape']::text[], 'Lesson: The Five Thiṇai', '/academy/lessons/five-thinai', '2026-09-01T09:00:00.000Z'),
  ('p-wordmap', null, true, 'showcase', 'Show a word you followed across literature', 'Pick a word, follow it from a kural to a Sangam poem to a Bhakti hymn. Share the three references you found and what changed in its meaning.', array['Reading Chamber', 'Words']::text[], 'Search a word', '/academy/search', '2026-09-01T09:00:00.000Z'),
  ('p-sandhi', null, true, 'collaborate', 'Help Solveli find sandhi-joined words', 'Search matches word parts inside lines, so joined forms like “யாது மூரே” (for யாதும் ஊரே) can be missed. Note any form you notice missing, with its verse reference.', array['Search', 'Sandhi', 'Help wanted']::text[], 'Try it on Puṟanāṉūṟu 192', '/academy/search?q=யாதும்', '2026-09-01T09:00:00.000Z')
